CREATE TABLE IF NOT EXISTS project_watch(avatar_id TEXT PRIMARY KEY REFERENCES avatars(id) ON DELETE CASCADE, enabled INTEGER NOT NULL DEFAULT 0, baseline_id TEXT, last_scan TEXT, error TEXT);
CREATE TABLE IF NOT EXISTS studio_snapshots(id TEXT PRIMARY KEY, avatar_id TEXT NOT NULL REFERENCES avatars(id) ON DELETE CASCADE, release_id TEXT REFERENCES releases(id) ON DELETE SET NULL, kind TEXT NOT NULL, label TEXT NOT NULL, platform TEXT NOT NULL, source TEXT NOT NULL, schema_version INTEGER NOT NULL DEFAULT 1, data_json TEXT NOT NULL CHECK(json_valid(data_json)), created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_studio_snapshots ON studio_snapshots(avatar_id,kind,created_at DESC);
CREATE TABLE IF NOT EXISTS development_batches(id TEXT PRIMARY KEY, avatar_id TEXT NOT NULL REFERENCES avatars(id) ON DELETE CASCADE, started_at TEXT NOT NULL, updated_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Review', data_json TEXT NOT NULL CHECK(json_valid(data_json)));
CREATE TABLE IF NOT EXISTS bugs(id TEXT PRIMARY KEY, avatar_id TEXT NOT NULL REFERENCES avatars(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', severity TEXT NOT NULL, status TEXT NOT NULL, found_version TEXT NOT NULL DEFAULT '', target_version TEXT NOT NULL DEFAULT '', steps TEXT NOT NULL DEFAULT '', expected TEXT NOT NULL DEFAULT '', actual TEXT NOT NULL DEFAULT '', known_issue INTEGER NOT NULL DEFAULT 0, attachment_ids TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(attachment_ids)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, resolved_at TEXT);
CREATE INDEX IF NOT EXISTS idx_bugs_avatar ON bugs(avatar_id,status);
CREATE TABLE IF NOT EXISTS work_sessions(id TEXT PRIMARY KEY, avatar_id TEXT NOT NULL REFERENCES avatars(id) ON DELETE CASCADE, version TEXT NOT NULL, description TEXT NOT NULL, status TEXT NOT NULL, started_at TEXT NOT NULL, heartbeat_at TEXT NOT NULL, ended_at TEXT, duration_seconds INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX IF NOT EXISTS one_running_work_session ON work_sessions(status) WHERE status='Running';
CREATE TABLE IF NOT EXISTS manual_dependencies(id TEXT PRIMARY KEY, avatar_id TEXT NOT NULL REFERENCES avatars(id) ON DELETE CASCADE, name TEXT NOT NULL, version TEXT NOT NULL, type TEXT NOT NULL, source TEXT NOT NULL, url TEXT NOT NULL, installed_path TEXT NOT NULL, notes TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS release_links(release_id TEXT PRIMARY KEY REFERENCES releases(id) ON DELETE CASCADE, avatar_id TEXT NOT NULL REFERENCES avatars(id) ON DELETE CASCADE, snapshot_ids TEXT NOT NULL DEFAULT '[]', known_issues_json TEXT NOT NULL DEFAULT '[]', api_before INTEGER, api_after INTEGER, upload_snapshot_id TEXT, association TEXT NOT NULL DEFAULT 'awaiting');
CREATE TABLE IF NOT EXISTS account_profiles(id TEXT PRIMARY KEY, display_name TEXT NOT NULL, image_url TEXT NOT NULL, created_at TEXT NOT NULL, last_authenticated TEXT, vrchat_user_id TEXT);
PRAGMA user_version=3;
